import { DefaultTheme } from "styled-components/dist/types";

export const lightTheme: DefaultTheme = {
	mode: "light",
	brandColors: {
		// primary: "#C2185B",
		primary: "#f0f4c3",
	},
	bgColors: {
		normal: "#eeeeee",
		reversed: "#212121",
		dimmed: "#ffffff",
	},
	textColors: {
		normal: "#212121",
		reversed: "#f5f5f5",
	},
	overlayColors: {
		lightBg: "#ffffff80",
		darkBg: "#21212180",
		red: "#F4433680",
		yellow: "#ffc10780",
		purple: "#9C27B080",
		blue: "#2196F380",
		lime: "#CDDC3980",
	},
}

export const darkTheme: DefaultTheme = {
	mode: "dark",
	brandColors: {
		// primary: "#e91e63",
		primary: "#CDDC39",
		// secondary: "#f0f4c3"
	},
	bgColors: {
		normal: "#212121",
		reversed: "#f5f5f5",
		dimmed: "#111111",
	},
	textColors: {
		normal: "#f5f5f5",
		reversed: "#212121",
	},
	overlayColors: {
		lightBg: "#ffffff80",
		darkBg: "#21212180",
		red: "#ff0000ed",
		yellow: "#ffc10780",
		purple: "#9C27B080",
		blue: "#2196F380",
		lime: "#CDDC3980",
	},
}
